UPDATE app_user
username = #{username}, display_name = #{displayName}, email = #{email}, timezone = COALESCE(#{timezone}, timezone), profile_picture_url = #{profilePictureUrl}, password_hash = #{passwordHash},
WHERE id = #{id}

UPDATE app_user
SET last_login_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE app_user
SET password_hash = #{passwordHash}
WHERE id = #{id}

UPDATE app_user
SET email = #{email}
WHERE id = #{id}

UPDATE app_user
SET email_verified = TRUE
WHERE id = #{id}

UPDATE app_user
SET profile_picture_url = #{profilePictureUrl}
WHERE id = #{id}

UPDATE app_user
SET timezone = #{timezone}
WHERE id = #{id}
